function b({registerIndicator:p,sourceValues:d,nulls:y}){p({id:"oa-hamma",name:"Hamming Moving Average (HAMMA)",category:"Trends FIR",placement:"onchart",inputs:[{key:"period",type:"number",label:"Period",default:10,min:1,max:5e3,step:1},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"hamma",type:"line",title:"HAMMA",style:{color:"#ffeb3b",lineWidth:2}}],calc(n,r){const M=Math.max(1,Math.floor(Number(r.period)||10)),i=d(n,r.source??"close"),c=n.length,m=new Array(c).fill(NaN);let o=[1],s=1;for(let t=0;t<c;t++){const a=Math.min(t+1,M);if(s!==a){o=new Array(a);for(let e=0;e<a;e++)o[e]=.54-.46*Math.cos(2*Math.PI*e/(a-1));s=a}let u=0,l=0;for(let e=0;e<a;e++){const h=i[t-e];Number.isFinite(h)&&(u+=h*o[e],l+=o[e])}const f=l!==0?u/l:NaN;m[t]=Number.isFinite(f)?f:i[t]}return{hamma:y(m)}}})}export{b as default};
